contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient balance");

        uint256 beforeTargetBalance = address(0).balance; // placeholder, replaced below
        // We cannot observe the hard-coded target directly except by its address, which is not available as a public member.
        // The rule must be re-expressed through c's observable surface. Since the target is a fixed address inside go(),
        // and we cannot pass it as a parameter, we cannot read its balance. Therefore the rule below uses only
        // c's balance and the test contract's balance, which are observable.

        uint256 cBefore = address(c).balance;
        uint256 testBefore = address(this).balance;

        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 cAfter = address(c).balance;
        uint256 testAfter = address(this).balance;

        // General rule: if go() succeeds, the test contract (owner) receives at least its pre-call balance minus the amount sent,
        // plus the contract's pre-call balance, because the contract forwards amount to the target and then sweeps the remaining
        // contract balance to the owner. Any Ether returned by the target can only increase the owner's final balance.
        assert(reverted || testAfter >= testBefore - amount + cBefore);
    }

    receive() external payable {}
}

